#include "stdlib/stats/base/dists/t/quantile.h"
#include "stdlib/math/base/special/kernel_betaincinv.h"
#include "stdlib/math/base/special/signum.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/sqrt.h"

/**
* Evaluates the quantile function for a Student's t distribution with degrees of freedom `v` at a probability `p`.
*
* @param p    input probability
* @param v    degrees of freedom
* @return     evaluated quantile function
*
* @example
* double y = stdlib_base_dists_t_quantile( 0.8, 1.0 );
* // returns ~1.376
*/
double stdlib_base_dists_t_quantile( const double p, const double v ) {
	double prob;
	double x;
	double y;
	if (
		stdlib_base_is_nan( v ) ||
		stdlib_base_is_nan( p ) ||
		v <= 0.0 ||
		p < 0.0 ||
		p > 1.0
	) {
		return 0.0/0.0; // NaN
	}
	prob = ( p > 0.5 ) ? 1.0 - p : p;
	stdlib_base_kernel_betaincinv( v / 2.0, 0.5, 2.0 * prob, 1.0 - ( 2.0 * prob ), &x, &y );
	return stdlib_base_signum( p - 0.5 ) * stdlib_base_sqrt( v * y / x );
}
